// HMAC-SHA256 verification of the incoming webhook.
// The portal signs the raw body with X-Kairikos-Portal-Signature header.
// Shared secret: N8N_WEBHOOK_SHARED_SECRET (set in n8n credential vault).
// Reject unsigned requests with 401.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SHARED_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SHARED_SECRET not configured'); }

const rawBody = $input.first().binary?.data?.data
  ? Buffer.from($input.first().binary.data.data, 'base64').toString('utf8')
  : JSON.stringify($input.first().json);

const providedSig = $input.first().headers['x-kairikos-portal-signature'] || '';
if (!providedSig) {
  throw new Error('Missing X-Kairikos-Portal-Signature header');
}

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
try {
  if (!crypto.timingSafeEqual(Buffer.from(providedSig, 'hex'), Buffer.from(expected, 'hex'))) {
    throw new Error('Invalid webhook signature');
  }
} catch (e) {
  if (e instanceof Error && (e.message === 'Invalid webhook signature' || e.message.startsWith('Invalid'))) {
    throw e;
  }
  // Length mismatch also throws — treat as invalid.
  throw new Error('Invalid webhook signature');
}

return [{ json: $input.first().json }];

// Secondary dedup check on eventId with 24h TTL.
// The portal is the primary idempotency boundary; this is belt-and-suspenders.
// In production: use a Redis node with SETEX. In dev/starter: skip with a mock.
// Shape of incoming event:
// {
//   eventId: string,        // unique per event, used as dedup key
//   eventType: 'config_complete',
//   clientId: string,
//   companyName: string,
//   contactEmail: string,
//   contactName: string,
//   tier: string,
//   completedAt: string,     // ISO-8601
//   stepsApproved: string[], // list of stepKeys that were approved
// }
// For now: just pass through. Redis integration is a future enhancement.
const event = $input.first().json;
console.log(`[config_complete] received event ${event.eventId} for client ${event.clientId}`);
return [{ json: { ...event, _dedupChecked: true } }];

